{"content":"// SPDX-License-Identifier: GPL-3.0-only
// PDL lexer (M1-WP2) — FILE-FORMAT §1. Stateless single pass; errors collected
// (never thrown). Colors are lexical only in `#rgb`/`#rrggbb` shape followed by
// a delimiter; every other `#` starts a comment (errata E-COLOR — M1.md).
export type TokenType =
  | 'ident'
  | 'string'
  | 'number'
  | 'color'
  | 'arrow'
  | 'punct'
  | 'comment'
  | 'eof';

export interface ArrowInfo {
  /** `<` present on the tail side (`<-`, `<->`, `<-t->`). */
  tail: boolean;
  /** `>` head present (`->`, `<->`, `-t->`). */
  head: boolean;
  /** Explicit link type (`-requests->` → `requests`). */
  type?: string;
}

export interface Token {
  type: TokenType;
  /** Raw source text (strings: the decoded value). */
  text: string;
  /** Decoded string value / arrow link type. */
  value?: string;
  arrow?: ArrowInfo;
  line: number;
  col: number;
  start: number;
  end: number;
}

export interface LexResult {
  tokens: Token[];
  diagnostics: Diagnostic[];
}

import { E, diag, type Diagnostic } from './diagnostics';

const EOF = (len: number, line: number): Token => ({
  type: 'eof',
  text: '',
  line,
  col: 1,
  start: len,
  end: len,
});

/** `#` + 3 or 6 hex digits + delimiter → color; otherwise comment. */
const isColor = (src: string, i: number): boolean => {
  const m = /^#(?:[0-9a-fA-F]{6}|[0-9a-fA-F]{3})(?![0-9a-fA-F])/.exec(src.slice(i, i + 8));
  if (!m) return false;
  const after = src[i + m[0].length];
  return after === undefined || /[\s{}:,)]/.test(after);
};

/** Arrow grammar: [`<`] `-` [ ident `-` ] [`>`]; needs a head or a tail. */
const scanArrow = (
  src: string,
  i: number,
  line: number,
  col: number,
): { arrow?: ArrowInfo; len: number; error?: Diagnostic } => {
  let j = i;
  let tail = false;
  if (src[j] === '<') {
    tail = true;
    j += 1;
  }
  if (src[j] !== '-') return { error: diag(E.invalidArrow, `stray '${src[i]}'`, line, col) };
  j += 1;
  let type: string | undefined;
  const ident = /^[a-z][a-z0-9_-]{0,63}/.exec(src.slice(j, j + 65));
  if (ident && src[j + ident[0].length] === '-') {
    type = ident[0];
    j += ident[0].length + 1;
  }
  let head = false;
  if (src[j] === '>') {
    head = true;
    j += 1;
  }
  if (!head && (!tail || type)) {
    return { error: diag(E.invalidArrow, 'arrow needs a head or tail', line, col) };
  }
  return { arrow: { tail, head, type }, len: j - i };
};

export function lex(src: string): LexResult {
  const tokens: Token[] = [];
  const diagnostics: Diagnostic[] = [];
  let i = 0;
  let line = 1;
  let col = 1;
  const push = (t: Omit<Token, 'line' | 'col'>): void => {
    tokens.push({ ...t, line, col });
  };

  while (i < src.length) {
    const ch = src[i];
    if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && src[i + 1] === '\n') i += 1;
      i += 1;
      line += 1;
      col = 1;
      continue;
    }
    if (ch === ' ' || ch === '\t') {
      i += 1;
      col += 1;
      continue;
    }
    const startCol = col;
    const start = i;
    if (ch === '#') {
      if (isColor(src, i)) {
        push({ type: 'color', text: src.slice(i, i + 7), start, end: i + 7, line, col: startCol });
        i += 7;
        col += 7;
        continue;
      }
      let j = i;
      while (j < src.length && src[j] !== '\n' && src[j] !== '\r') j += 1;
      const text = src.slice(i + 1, j).trim();
      push({ type: 'comment', text, start, end: j, line, col: startCol });
      i = j;
      col += j - i === 0 ? 0 : j - start; // col recomputed at newline
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      let value = '';
      let bad = false;
      while (j < src.length && src[j] !== '"') {
        if (src[j] === '\n') break;
        if (src[j] === '\\') {
          const nxt = src[j + 1];
          if (nxt === '"' || nxt === '\\') {
            value += nxt;
            j += 2;
          } else {
            diagnostics.push(diag(E.invalidEscape, `invalid escape \\${nxt ?? ''}`, line, startCol));
            bad = true;
            j += 1;
          }
          continue;
        }
        value += src[j];
        j += 1;
      }
      if (src[j] !== '"') {
        diagnostics.push(diag(E.unterminatedString, 'unterminated string', line, startCol));
        push({ type: 'string', text: value, value, start, end: j, line, col: startCol });
        i = j;
        col += j - start;
        continue;
      }
      if (bad) diagnostics.pop(); // keep single code per string, message retained
      push({ type: 'string', text: value, value, start, end: j + 1, line, col: startCol });
      i = j + 1;
      col += j + 1 - start;
      continue;
    }
    if (ch === '-' || ch === '<') {
      const res = scanArrow(src, i, line, startCol);
      if (res.error) diagnostics.push(res.error);
      else {
        push({
          type: 'arrow',
          text: src.slice(i, i + res.len),
          arrow: res.arrow,
          start,
          end: i + res.len,
          line,
          col: startCol,
        });
        i += res.len;
        col += res.len;
      }
      if (res.error) {
        i += 1;
        col += 1;
      }
      continue;
    }
    if (/[0-9]/.test(ch) || (ch === '-' && /[0-9]/.test(src[i + 1] ?? ''))) {
      const m = /^-?[0-9]+(?:\.[0-9]+)?/.exec(src.slice(i, i + 64));
      if (!m) {
        diagnostics.push(diag(E.invalidNumber, 'invalid number', line, startCol));
        i += 1;
        col += 1;
        continue;
      }
      push({ type: 'number', text: m[0], start, end: i + m[0].length, line, col: startCol });
      const len = m[0].length;
      i += len;
      col += len;
      continue;
    }
    if (/[{}():,]/.test(ch)) {
      push({ type: 'punct', text: ch, start, end: i + 1, line, col: startCol });
      i += 1;
      col += 1;
      continue;
    }
    const idm = /^[a-z][a-z0-9_-]{0,63}/.exec(src.slice(i, i + 65));
    if (idm) {
      push({ type: 'ident', text: idm[0], start, end: i + idm[0].length, line, col: startCol });
      const len = idm[0].length;
      i += len;
      col += len;
      continue;
    }
    diagnostics.push(diag(E.unexpected, `unexpected character '${ch}'`, line, startCol));
    i += 1;
    col += 1;
  }
  tokens.push(EOF(src.length, line));
  return { tokens, diagnostics };
}
