// attribute per line, 2-space indent, quotes on strings, minimal link ids
// (emitted only when referenced by a flow step — D-M1-16), blank line between
// sections, comments re-attached above their statement (D-M1-10/12).
import type {
  Branch, Comments, Doc, Flow, FlowStep, ImportStmt, Link, Obj, StyleBlock,
  StyleStmt, View, ViewLine,
} from '../model/types';

const INDENT = '  ';

/** Quote a string literal with PDL escapes (`\` and `"` only, §1). */
export function quote(s: string): string {
  return `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

class Printer {
  private out: string[] = [];

  add(line: string): void {
    this.out.push(line);
  }
  blank(): void {
    if (this.out.length > 0 && this.out[this.out.length - 1] !== '') this.out.push('');
  }
  comment(c: Comments | undefined, depth: number): void {
    if (!c) return;
    for (const line of c) this.out.push(INDENT.repeat(depth) + '# ' + line);
  }
  text(): string {
    return this.out.join('\n') + '\n';
  }
}

const styleLines = (sb: StyleBlock, depth: number, p: Printer): void => {
  if (sb.fill) p.add(`${INDENT.repeat(depth)}fill ${sb.fill}`);
  if (sb.stroke) p.add(`${INDENT.repeat(depth)}stroke ${sb.stroke}`);
  if (sb.text) p.add(`${INDENT.repeat(depth)}text ${sb.text}`);
  if (sb.icon) p.add(`${INDENT.repeat(depth)}icon ${sb.icon}`);
  if (sb.shape) p.add(`${INDENT.repeat(depth)}shape ${sb.shape}`);
  if (sb.dashed) p.add(`${INDENT.repeat(depth)}dashed`);
  for (const r of sb.raw ?? []) p.add(`${INDENT.repeat(depth)}${r.raw}`);
};

const hasStyle = (sb: StyleBlock | undefined): boolean =>
  !!sb && (sb.fill !== undefined || sb.stroke !== undefined || sb.text !== undefined ||
    sb.icon !== undefined || sb.shape !== undefined || sb.dashed === true || (sb.raw?.length ?? 0) > 0);

const arrowFor = (l: Link): string => (l.bidir ? '<->' : l.type ? `-${l.type}->` : '->');

const stepText = (s: FlowStep, depth: number, p: Printer): void => {
  p.comment(s.comments, depth);
  const pad = INDENT.repeat(depth);
  switch (s.type) {
    case 'intro':
    case 'info':
    case 'conclusion':
      p.add(`${pad}${s.type} ${quote(s.text)}`);
      return;
    case 'process': {
      const body = s.text === undefined ? `process ${s.target}` : `process ${s.target} ${quote(s.text)}`;
      p.add(pad + body);
      return;
    }
    case 'msg': {
      let line = `${s.from} ${arrowFor(s as unknown as Link)} ${s.to}`;
      if (s.label !== undefined) line += ` : ${quote(s.label)}`;
      if (s.linkRef !== undefined) line += ` as ${s.linkRef}`;
      if (s.flip === true) line += ' flip';
      p.add(pad + line);
      return;
    }
    case 'goto': {
      const g = s as unknown as { file?: string; flow: string; ret?: 'here' };
      const target = g.file === undefined ? g.flow : quote(`${g.file}#${g.flow}`);
      p.add(`${pad}goto ${target}${g.ret === 'here' ? ' return here' : ''}`);
      return;
    }
    case 'alt': {
      const a = s as unknown as { label?: string; branches: Branch[] };
      p.add(`${pad}alt${a.label === undefined ? '' : ' ' + quote(a.label)} {`);
      for (const b of a.branches) {
        p.comment(b.comments, depth + 1);
        p.add(`${INDENT.repeat(depth + 1)}${quote(b.label)} {`);
        for (const st of b.steps) stepText(st, depth + 2, p);
        p.add(`${INDENT.repeat(depth + 1)}}`);
      }
      p.add(`${pad}}`);
      return;
    }
    case 'par': {
      const pr = s as unknown as { label?: string; lanes: FlowStep[][] };
      p.add(`${pad}par${pr.label === undefined ? '' : ' ' + quote(pr.label)} {`);
      for (const lane of pr.lanes) {
        p.add(`${INDENT.repeat(depth + 1)}{`);
        for (const st of lane) stepText(st, depth + 2, p);
        p.add(`${INDENT.repeat(depth + 1)}}`);
      }
      p.add(`${pad}}`);
      return;
    }
  }
};

const printObject = (o: Obj, p: Printer): void => {
  p.comment(o.comments, 0);
  const name = o.name ?? o.id;
  if (!hasStyle(o.style) && (o.attributes?.length ?? 0) === 0) {
    // single-line fast path keeps canonical output compact for simple objects
  }
  p.add(`${o.kind} ${o.id} ${quote(name)} {`);
  let d = 1;
  if (o.description !== undefined) p.add(`${INDENT}description ${quote(o.description)}`);
  if (o.technology !== undefined) p.add(`${INDENT}technology ${quote(o.technology)}`);
  if (o.tags?.length) p.add(`${INDENT}tag ${o.tags.join(' ')}`);
  for (const pr of o.properties ?? []) p.add(`${INDENT}property ${pr.key} ${quote(pr.value)}`);
  if (o.contains?.length) p.add(`${INDENT}contains ${o.contains.join(' ')}`);
  if (o.attach !== undefined) p.add(`${INDENT}attach ${o.attach}`);
  if (o.icon !== undefined) p.add(`${INDENT}icon ${o.icon}`);
  if (hasStyle(o.style)) {
    p.add(`${INDENT}style {`);
    styleLines(o.style, 2, p);
    p.add(`${INDENT}}`);
  }
  for (const r of o.attributes ?? []) p.add(`${INDENT}${r.raw}`);
  p.add('}');
};

/** Link id referenced by any flow msg step? (§4 minimal-noise rule, D-M1-16) */
const referencedLinkIds = (doc: Doc): Set<string> => {
  const refs = new Set<string>();
  const collect = (steps: FlowStep[]): void => {
    for (const s of steps) {
      if (s.type === 'msg' && s.linkRef !== undefined) refs.add(s.linkRef);
      if (s.type === 'alt') for (const b of (s as unknown as { branches: Branch[] }).branches) collect(b.steps);
      if (s.type === 'par') for (const lane of (s as unknown as { lanes: FlowStep[][] }).lanes) collect(lane);
    }
  };
  for (const f of doc.flows) collect(f.steps);
  return refs;
};

const printLink = (l: Link, emitId: boolean, p: Printer): void => {
  p.comment(l.comments, 0);
  let line = `${l.from} ${arrowFor(l)} ${l.to}`;
  if (l.label !== undefined) line += ` : ${quote(l.label)}`;
  if (emitId && l.id !== undefined) line += ` as ${l.id}`;
  const needsBlock = hasStyle(l.style) || (l.waypoints?.length ?? 0) > 0 || (l.attributes?.length ?? 0) > 0;
  if (!needsBlock) {
    p.add(line);
    return;
  }
  p.add(line + ' {');
  if (hasStyle(l.style)) {
    p.add(`${INDENT}style {`);
    styleLines(l.style, 2, p);
    p.add(`${INDENT}}`);
  }
  for (const w of l.waypoints ?? []) p.add(`${INDENT}waypoint (${w[0]}, ${w[1]})`);
  for (const r of l.attributes ?? []) p.add(`${INDENT}${r.raw}`);
  p.add('}');
};

const printFlow = (f: Flow, p: Printer): void => {
  p.comment(f.comments, 0);
  let head = 'flow';
  if (f.title !== undefined) head += ' ' + quote(f.title);
  if (f.id !== undefined) head += ` as ${f.id}`;
  p.add(head + ' {');
  for (const s of f.steps) stepText(s, 1, p);
  p.add('}');
};

const printViewLine = (l: ViewLine, p: Printer): void => {
  p.comment(l.comments, 1);
  switch (l.type) {
    case 'layout':
      p.add(l.mode === 'saved' ? `${INDENT}layout saved` : `${INDENT}layout auto ${l.dir}`);
      return;
    case 'hideTag':
      p.add(`${INDENT}hide tag ${l.id}`);
      return;
    case 'hide':
      p.add(`${INDENT}hide ${l.id}`);
      return;
    case 'position':
      p.add(`${INDENT}position ${l.id} (${l.x}, ${l.y})`);
      return;
    case 'pin':
      p.add(`${INDENT}pin ${l.id}`);
      return;
  }
};

const printView = (v: View, p: Printer): void => {
  p.comment(v.comments, 0);
  let head = `view ${quote(v.name)}`;
  if (v.id !== undefined) head += ` as ${v.id}`;
  p.add(head + ' {');
  for (const l of v.lines) printViewLine(l, p);
  p.add('}');
};

const printStyleStmt = (st: StyleStmt, p: Printer): void => {
  p.comment(st.comments, 0);
  p.add(`style ${st.target} {`);
  styleLines(st.style, 1, p);
  p.add('}');
};

const printImport = (imp: ImportStmt, p: Printer): void => {
  p.comment(imp.comments, 0);
  p.add(`import ${imp.alias} as ${quote(imp.path)}`);
};

/** Print a Doc to canonical PDL (§11). Idempotent: print∘parse∘print = print. */
export function printDoc(doc: Doc): string {
  const p = new Printer();
  p.add(`pcd ${doc.formatVersion}`);
  p.comment(doc.comments, 0);
  if (doc.title !== undefined) p.add(`title ${quote(doc.title)}`);
  if (doc.level !== undefined) p.add(`level ${doc.level}`);
  if (doc.direction !== undefined) p.add(`direction ${doc.direction}`);
  if (doc.theme !== undefined) p.add(`theme ${doc.theme}`);
  if (doc.imports.length > 0) {
    p.blank();
    for (const imp of doc.imports) printImport(imp, p);
  }
  const refs = referencedLinkIds(doc);
  if (doc.objects.length > 0) {
    p.blank();
    for (const o of doc.objects) printObject(o, p);
  }
  if (doc.links.length > 0) {
    p.blank();
    for (const l of doc.links) printLink(l, refs.has(l.id ?? ''), p);
  }
  if (doc.flows.length > 0) {
    p.blank();
    for (const f of doc.flows) printFlow(f, p);
  }
  if (doc.views.length > 0) {
    p.blank();
    for (const v of doc.views) printView(v, p);
  }
  if (doc.styles.length > 0) {
    p.blank();
    for (const st of doc.styles) printStyleStmt(st, p);
  }
  return p.text();
}
