{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Canonical printer tests (M1-WP3): §11 rules, idempotence fuzz (seeded),
// round-trip property print∘parse∘print + IR equality modulo positions.
import { describe, expect, it } from 'vitest';
import { parsePDL } from './parser';
import { printDoc } from './printer';
import { forAllSeeds, type Rng } from './fuzz';
import { serializeDoc } from '../model/serialize';
import { IR_VERSION, type Doc, type FlowStep, type Obj } from '../model/types';
import { CHECKOUT_SRC } from './format.testdata';

const ID_POOL = ['user', 'shop', 'api', 'db', 'events', 'psp', 'ctx', 'n1'] as const;
const KINDS = ['person', 'system', 'system_ext', 'container', 'component', 'datastore', 'queue', 'group', 'note'] as const;
const NASTY = [
  'plain', 'with space', 'quote " inside', 'back\\slash', 'hash # not comment',
  'unicode é☃ 字', 'trailing  ', ' leading', '', 'L1', 'multi\nline? no',
] as const;

const pos = (n: number) => ({ line: n, col: 1 });

const genObject = (rng: Rng, id: string): Obj => ({
  kind: rng.pick(KINDS),
  id,
  name: rng.bool(0.8) ? rng.pick(NASTY) : undefined,
  description: rng.bool(0.5) ? rng.pick(NASTY) : undefined,
  technology: rng.bool(0.4) ? rng.pick(NASTY) : undefined,
  tags: rng.bool(0.4) ? rng.some(['core', 'pci', 'web'], 3) : undefined,
  properties: rng.bool(0.3) ? [{ key: 'owner', value: rng.pick(NASTY) }] : undefined,
  contains: rng.bool(0.2) ? ['api', 'db'].slice(0, 1 + rng.int(2)) : undefined,
  attach: rng.bool(0.2) ? 'api' : undefined,
  icon: rng.bool(0.2) ? 'cloud' : undefined,
  comments: rng.bool(0.3) ? ['note about ' + id] : undefined,
  pos: pos(0),
});

const genStep = (rng: Rng, depth: number): FlowStep => {
  const roll = rng.next();
  const p = pos(0);
  if (depth < 2 && roll < 0.15) {
    return {
      type: 'alt', label: rng.pick(NASTY), pos,
      branches: [0, 1].map((i) => ({ label: `branch ${i}`, steps: [genStep(rng, depth + 1)], pos })),
    };
  }
  if (depth < 2 && roll < 0.3) {
    return {
      type: 'par', label: rng.pick(NASTY), pos,
      lanes: [[genStep(rng, depth + 1)], []],
    };
  }
  if (roll < 0.55) {
    return {
      type: 'msg', from: rng.pick(ID_POOL), to: rng.pick(ID_POOL), pos,
      label: rng.bool(0.6) ? rng.pick(NASTY) : undefined,
      linkRef: rng.bool(0.4) ? 'L1' : undefined,
      flip: rng.bool(0.2) || undefined,
    };
  }
  if (roll < 0.7) return { type: 'process', target: rng.pick(ID_POOL), text: rng.bool(0.5) ? rng.pick(NASTY) : undefined, pos };
  if (roll < 0.8) return { type: 'goto', flow: 'other', file: rng.bool(0.3) ? 'billing/refunds.pcd' : undefined, ret: rng.bool(0.3) ? 'here' : undefined, pos };
  if (roll < 0.9) return { type: 'intro', text: rng.pick(NASTY), pos };
  return { type: 'conclusion', text: rng.pick(NASTY), pos };
};

const genDoc = (rng: Rng): Doc => {
  const ids = rng.some(ID_POOL, 5);
  const uniq = [...new Set(ids.length ? ids : ['x1'])];
  const objects = uniq.map((id) => genObject(rng, id));
  const links = uniq.length >= 2
    ? [{ from: uniq[0]!, to: uniq[1]!, id: 'L1', type: rng.bool(0.5) ? 'requests' : undefined, label: rng.pick(NASTY), bidir: rng.bool(0.2) || undefined, waypoints: rng.bool(0.3) ? [[120, 300]] : undefined, pos: pos(0) }]
    : [];
  const flows = rng.bool(0.7)
    ? [{ id: rng.bool(0.7) ? 'f1' : undefined, title: rng.pick(NASTY), steps: [genStep(rng, 0), genStep(rng, 0)], pos: pos(0) }]
    : [];
  const views = rng.bool(0.5)
    ? [{ id: 'v1', name: rng.pick(NASTY), pos: pos(0), lines: [
        { type: rng.bool(0.5) ? 'layout' : 'hide', mode: 'auto', dir: rng.pick(['LR', 'TB', 'RL', 'BT'] as const), id: 'db', pos } as const,
        { type: 'position', id: uniq[0]!, x: 0, y: 120, pos } as const,
      ] }]
    : [];
  const styles = rng.bool(0.4)
    ? [{ target: uniq[0]!, style: { fill: '#2d6cdf', dashed: rng.bool(0.5) || undefined, raw: rng.bool(0.3) ? [{ raw: 'blur 2px', pos }] : undefined }, pos: pos(0) }]
    : [];
  return {
    irVersion: IR_VERSION,
    formatVersion: '1.0',
    title: rng.bool(0.6) ? rng.pick(NASTY) : undefined,
    level: rng.bool(0.5) ? 'container' : undefined,
    direction: rng.bool(0.5) ? rng.pick(['LR', 'TB', 'RL', 'BT'] as const) : undefined,
    theme: rng.bool(0.3) ? 'dark' : undefined,
    comments: rng.bool(0.4) ? ['doc note', 'second'] : undefined,
    imports: rng.bool(0.4) ? [{ alias: 'common', path: '../common/actors.pcd', comments: rng.bool(0.3) ? ['imp'] : undefined, pos: pos(0) }] : [],
    objects, links, flows, views, styles,
  };
};

/** Positions differ after re-parse; compare IR modulo pos + comments order. */
const stripVolatile = (d: Doc): unknown =>
  JSON.parse(serializeDoc(strip(d)));

const strip = (d: Doc): Doc => ({
  ...d,
  comments: undefined,
  objects: d.objects.map((o) => ({ ...o, pos: { line: 0, col: 0 }, comments: o.comments })),
  links: d.links.map((l) => ({ ...l, pos: { line: 0, col: 0 } })),
  flows: d.flows.map((f) => ({ ...f, pos: { line: 0, col: 0 }, steps: f.steps.map((s) => ({ ...s, pos: { line: 0, col: 0 } })) })),
  views: d.views.map((v) => ({ ...v, pos: { line: 0, col: 0 }, lines: v.lines.map((l) => ({ ...l, pos: { line: 0, col: 0 } })) })),
  styles: d.styles.map((s) => ({ ...s, pos: { line: 0, col: 0 } })),
  imports: d.imports.map((i) => ({ ...i, pos: { line: 0, col: 0 } })),
});

describe('printer (WP3)', () => {
  it('checkout sample: canonical output is stable and idempotent', () => {
    const d1 = parsePDL(CHECKOUT_SRC).doc!;
    const p1 = printDoc(d1);
    const d2 = parsePDL(p1).doc!;
    const p2 = printDoc(d2);
    expect(p2).toBe(p1);
    expect(d2!.diagnosticsSafe()).toBeUndefined(); // no-op guard
    // link id L1 is referenced by no flow step in canonical form? L4/L3 are:
    expect(p1).toContain(' as L4');
    expect(p1).not.toContain('-writes-> db as');
  });

  it('round-trips the checkout sample with equal IR (modulo positions)', () => {
    const d1 = parsePDL(CHECKOUT_SRC).doc!;
    const p1 = printDoc(d1);
    const d2 = parsePDL(p1).doc!;
    expect(stripVolatile(d2)).toEqual(stripVolatile(d1));
  });

  it('quotes and escapes strings round-trip safely', () => {
    const { doc } = parsePDL('pcd 1.0\nsystem a "say \\"hi\\\\" ');
    const printed = printDoc(doc!);
    expect(printed).toContain('"say \\"hi\\\\""');
    const r = parsePDL(printed);
    expect(r.doc!.objects[0]!.name).toBe('say "hi\\');
  });

  it('idempotence + IR-stability fuzz (50 seeds)', () => {
    forAllSeeds(Array.from({ length: 50 }, (_, k) => k + 1), (rng, seed) => {
      const doc = genDoc(rng);
      const p1 = printDoc(doc);
      const r = parsePDL(p1);
      if (!r.doc) throw new Error(`seed ${seed}: reparse failed:\n${p1}\n${JSON.stringify(r.diagnostics)}`);
      const p2 = printDoc(r.doc);
      if (p2 !== p1) throw new Error(`seed ${seed}: not idempotent:\n--- p1\n${p1}\n--- p2\n${p2}`);
      const a = JSON.stringify(strip(doc));
      const b = JSON.stringify(strip(r.doc));
      if (a !== b) throw new Error(`seed ${seed}: IR drift\n--- a\n${a}\n--- b\n${b}`);
    });
  });
});
