        type: rng.bool(0.4) ? 'requests' : undefined,
        label: rng.bool(0.8) ? rng.pick(NASTY) : undefined,
        bidir: rng.bool(0.2) || undefined,
        waypoints: rng.bool(0.3) ? [[120, 300]] : undefined,
        pos: pos(0),
      }]
    : [];
  return {
    irVersion: IR_VERSION,
    formatVersion: '1.0',
    title: hasTitle ? rng.pick(NASTY) : undefined,
    level: rng.bool(0.5) ? 'container' : undefined,
    direction: rng.bool(0.5) ? rng.pick(['LR', 'TB', 'RL', 'BT'] as const) : undefined,
    theme: rng.bool(0.3) ? 'dark' : undefined,
    comments: hasTitle && rng.bool(0.4) ? ['doc note', 'second'] : undefined,
    imports: rng.bool(0.4)
      ? [{ alias: 'common', path: '../common/actors.pcd', comments: rng.bool(0.3) ? ['imp'] : undefined, pos: pos(0) }]
      : [],
    objects,
    links,
    flows: rng.bool(0.7)
      ? [{ id: rng.bool(0.7) ? 'f1' : undefined, title: rng.pick(NASTY), steps: [genStep(rng, 0), genStep(rng, 0)], pos: pos(0) }]
      : [],
    views: rng.bool(0.5)
      ? [{
          id: 'v1', name: rng.pick(NASTY), pos: pos(0),
          lines: [
            (rng.bool(0.5)
              ? { type: 'layout', mode: 'auto', dir: rng.pick(['LR', 'TB', 'RL', 'BT'] as const) }
              : { type: 'hide', id: 'db' }) as ViewLine,
            { type: 'position', id: uniq[0]!, x: 0, y: 120 } as ViewLine,
          ],
