const strip = (d: Doc): unknown =>
  JSON.parse(JSON.stringify({
    ...d,
    objects: d.objects.map((o) => ({ ...o, pos: { line: 0, col: 0 }, name: o.name ?? o.id })),
    links: d.links.map((l) => ({ ...l, pos: { line: 0, col: 0 } })),
    flows: d.flows.map((f) => ({
      ...f, pos: { line: 0, col: 0 },
      steps: f.steps.map(normStep),
    })),
    views: d.views.map((v) => ({
      ...v, pos: { line: 0, col: 0 },
      lines: v.lines.map((l) => ({ ...l, pos: { line: 0, col: 0 } })),
    })),
    styles: d.styles.map((s) => ({ ...s, pos: { line: 0, col: 0 } })),
    imports: d.imports.map((i) => ({ ...i, pos: { line: 0, col: 0 } })),
  }));

const normStep = (s: FlowStep): FlowStep => {
  const base = { ...s, pos: { line: 0, col: 0 } } as FlowStep;
  if (base.type === 'alt') {
    return { ...base, branches: (base as { branches: { label: string; steps: FlowStep[] }[] }).branches.map((b) => ({
      ...b, steps: b.steps.map(normStep),
    })) } as FlowStep;
  }
  if (base.type === 'par') {
    return { ...base, lanes: (base as { lanes: FlowStep[][] }).lanes.map((lane) => lane.map(normStep)) } as FlowStep;
  }
  return base;
};

describe('printer (WP3)', () => {
  it('checkout sample: canonical output is stable and idempotent', () => {
    const d1 = parsePDL(CHECKOUT_SRC).doc!;
    const p1 = printDoc(d1);
    const d2 = parsePDL(p1).doc!;
    const p2 = printDoc(d2);
