+const strip = (d: Doc): unknown => {
+  const j: unknown = JSON.parse(JSON.stringify(d));
+  zeroPos(j);
+  const r = j as { objects: { name?: string; id: string }[] };
+  for (const o of r.objects) if (o.name === undefined) o.name = o.id;
+  return j;
